// Moz crawl issues we can catch before they ship. Run after `npm run build`:
// `npm run check:crawl`.
//
//   missing canonical     an indexable page with no <link rel="canonical">
//   has meta noindex      any page other than the allowlist below
//   title too long        rendered <title> wider than ~600px (Moz's cutoff)
//   thin content          indexable HTML authored in public/ with under 250 words
//                         outside <script>, <style>, and <svg>
//
// public/agents/ is generated by dna-codes-platform and is not edited here, so it
// is skipped. The CMS admin at /decapcms/ is the one page allowed to be noindex.

import { existsSync, readFileSync, readdirSync } from 'node:fs';
import { join, dirname, resolve, relative, sep } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const dist = join(root, 'dist');
const publicDir = join(root, 'public');
const TITLE_LIMIT_PX = 600;
const THIN_WORDS = 250;
const SKIP_DIRS = new Set(['agents', '_astro']);

// Unscaled Arial-ish advances, then × SCALE so the samples from the 2026-11-09
// Moz export land within about 20px of the pixel length Moz reported. The gate
// stays at Moz's 600. Keep titles under ~560 so that error still clears it.
const SCALE = 1.22;
const WIDTH = {
  ' ': 4.45,
  "'": 3.1,
  ',': 4.4,
  '-': 5.3,
  '.': 4.4,
  ':': 4.4,
  ';': 4.4,
  '?': 8.9,
  I: 4.5,
  J: 8,
  W: 15.2,
  i: 3.6,
  j: 3.6,
  l: 3.6,
  f: 4.5,
  t: 4.5,
  r: 5.3,
  m: 13.4,
  w: 11.6,
  '—': 15.2,
  '–': 8.9,
  '’': 3.1,
};

if (!existsSync(join(dist, 'index.html'))) {
  console.error('crawl-check: dist/index.html not found. Run `npm run build` first.');
  process.exit(1);
}

const failures = [];
const fail = (check, detail) => failures.push({ check, detail });

const htmlFiles = [];
(function walk(dir) {
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const p = join(dir, entry.name);
    if (entry.isDirectory()) {
      if (dir === dist && SKIP_DIRS.has(entry.name)) continue;
      walk(p);
    } else if (entry.name.endsWith('.html')) htmlFiles.push(p);
  }
})(dist);

const attr = (tag, name) => tag.match(new RegExp(`\\b${name}=["']?([^"'\\s>]+)`, 'i'))?.[1];
const routeOf = (file) =>
  '/' +
  relative(dist, file)
    .split(sep)
    .join('/')
    .replace(/(^|\/)index\.html$/, '')
    .replace(/\.html$/, '');

const decode = (value) =>
  value
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&apos;|&#0?39;/g, "'")
    .replace(/&mdash;|&#8212;/g, '—')
    .replace(/&ndash;|&#8211;/g, '–')
    .replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(Number(n)))
    .replace(/\s+/g, ' ')
    .trim();

const titleOf = (html) => decode(html.match(/<title[^>]*>([\s\S]*?)<\/title>/i)?.[1] ?? '');

const titlePixels = (title) => Math.round([...title].reduce((n, ch) => n + (WIDTH[ch] ?? 9), 0) * SCALE);

const robotsContent = (html) => {
  for (const tag of html.match(/<meta\b[^>]*>/gi) ?? []) {
    const name = (attr(tag, 'name') || '').toLowerCase();
    if (name === 'robots' || name === 'googlebot') return (attr(tag, 'content') || '').toLowerCase();
  }
  return '';
};

// Page 2+ of the blog, a tag, or a category is an archive slice. The list route
// already marks those noindex. Tag page 1 (/tag/bpmn) does not match.
const paginatedArchive = (route) => /^\/(?:blog|tag\/[^/]+|category\/[^/]+)\/\d+$/.test(route);
const noindexAllowed = (route) => route === '/decapcms' || route.startsWith('/decapcms/') || paginatedArchive(route);

const bodyWords = (html) => {
  const text = html
    .replace(/<script\b[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style\b[\s\S]*?<\/style>/gi, ' ')
    .replace(/<svg\b[\s\S]*?<\/svg>/gi, ' ')
    .replace(/<noscript\b[\s\S]*?<\/noscript>/gi, ' ')
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&[a-z#0-9]+;/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  return text ? text.split(' ').filter(Boolean).length : 0;
};

let pages = 0;
for (const file of htmlFiles) {
  const html = readFileSync(file, 'utf8');
  if (/http-equiv=["']?refresh/i.test(html)) continue;
  pages++;
  const route = routeOf(file) || '/';
  const robots = robotsContent(html);
  const noindex = /\bnoindex\b/.test(robots);

  if (noindex && !noindexAllowed(route)) {
    fail('noindex', `${route} has meta noindex. Index it, or add it to the allowlist in scripts/crawl-check.mjs.`);
  }

  const indexable = !noindex;
  if (indexable && !/<link\b[^>]*rel=["']?canonical/i.test(html)) {
    fail('canonical', `${route} is indexable and has no canonical URL.`);
  }

  if (indexable) {
    const title = titleOf(html);
    const px = titlePixels(title);
    if (title && px > TITLE_LIMIT_PX) {
      fail('title', `${route} title is about ${px}px (limit ${TITLE_LIMIT_PX}): ${title}`);
    }
  }

  const fromPublic = existsSync(join(publicDir, relative(dist, file)));
  if (indexable && fromPublic) {
    const words = bodyWords(html);
    if (words < THIN_WORDS) {
      fail(
        'thin-content',
        `${route} has ${words} words outside script and style (needs ${THIN_WORDS}). The copy has to be in the HTML body, not only in a script.`
      );
    }
  }
}

if (failures.length) {
  console.error(`crawl-check: ${failures.length} problem(s) across ${pages} pages\n`);
  for (const { check, detail } of failures) console.error(`  ✗ [${check}] ${detail}`);
  console.error('\nThese are the Moz crawl issues this site has shipped before. See AGENTS.md, "Search crawl".');
  process.exit(1);
}

console.log(`crawl-check: ${pages} pages pass canonical, index, title width, and thin content.`);
